cases() {
  return [
    { no: "CASE 01", title: "工業系サイトリニューアル", roles: ["ヒアリング〜公開"], point: "クライアントのお考えや要望を整理しながら仕様を確定。制作進行・確認・公開まで担当。", result: "結果：当初予定より4日前倒しで公開。" },
    { no: "CASE 02", title: "外国人エンジニア派遣サイト", roles: ["3C分析", "業界調査", "ワイヤーフレーム", "英語版ワイヤーフレーム"], point: "サービス・競合・ターゲットを整理し、企業の強みが伝わるサイト構成を設計。", result: "結果：サービスの強みを整理したサイト構成を評価いただいた。" },
