  ];
}

renderVals() {
  const open = this.state.menu;
  const other = this.state.other;
  const sent = this.state.sent;
  const cur = this.cases()[this.state.modal] || { no: "", title: "", roles: [], point: "", result: "" };
  return {
    menuOpen: open,
    toggleMenu: () => this.setState((s) => ({ menu: !s.menu })),
    closeMenu: () => this.setState({ menu: false }),
    heroNavClass: "hero-nav" + (open ? " is-open" : ""),
    menuClass: "menu" + (open ? " is-open" : ""),
    formFieldsetClass: "form__fieldset" + (other ? " is-other" : ""),
    pickGenre: () => { if (this.state.other) this.setState({ other: false }); },
    pickOther: () => this.setState({ other: true }),
