439:.work-card { display: flex; flex-direction: column; cursor: pointer; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 26px; overflow: hidden; box-shadow: 8px 8px 0 #172E4A; transition: transform .2s ease; }
440:.work-card:hover { transform: translate(-2px,-2px); }
441:.work-card__media { position: relative; aspect-ratio: 4/3; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); overflow: hidden; }
442:.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; }
443:.work-card__media--placeholder { display: flex; align-items: center; justify-content: center; }
444:.work-card__media--placeholder span { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
445:.work-card__body { padding: 26px clamp(20px,3vw,28px) 28px; display: flex; flex-direction: column; gap: 18px; }
446:.work-card__no { margin: 0; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
447:.work-card__title { margin: 10px 0 0; font-weight: 700; font-size: 20px; line-height: 1.5; color: #172E4A; }
448:.work-card__field-label { margin: 0 0 8px; font-size: 10px; letter-spacing: 0.18em; color: #A7AFBC; text-transform: uppercase; }
449:.work-card__roles { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
450:.work-card__role { font-size: 12px; color: #3E4A5C; background: rgba(23,46,74,0.07); border-radius: 999px; padding: 5px 12px; white-space: nowrap; }
451:.work-card__text { margin: 0; font-size: 13px; line-height: 1.95; color: #56637A; }
452:.work-card__result { margin: 0; padding: 14px 18px; background: rgba(220,133,65,0.1); border-left: 10px solid #DC8541; border-radius: 14px; font-size: 13px; font-weight: 700; color: #A85A1E; line-height: 1.75; }
453:.work-card__result--stat { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; }
454:.work-card__result-pre { margin: 0; font-size: 12px; font-weight: 500; }
455:.work-card__result-num { font-size: clamp(40px,7vw,64px); font-weight: 900; line-height: 1; }
456:.work-card__result-unit { font-size: 14px; font-weight: 700; }
457:.work-card__result-note { margin: -6px 0 0; font-size: 11.5px; color: #8A93A3; }
458:.work-card__more { margin: 0; display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; color: #A85A1E; }
461:  .work-card--feature { display: grid; grid-template-columns: 42% 1fr; align-items: stretch; }
462:  .work-card--feature .work-card__media { aspect-ratio: auto; height: 100%; min-height: 320px; }
463:  .work-card--feature .work-card__body { justify-content: center; padding: clamp(30px,3.4vw,40px); }
