/* ============================================
   work-card（WORKS／画像タイル。詳細情報はすべてモーダル側で表示）
   ============================================ */
.work-grid { display: grid; grid-template-columns: 1fr; gap: 20px; }
.work-card { position: relative; display: block; cursor: pointer; border: 3px solid #172E4A; border-radius: 24px; overflow: hidden; box-shadow: 8px 8px 0 #172E4A; transition: transform .2s ease, box-shadow .2s ease; }
.work-card:hover, .work-card:focus-visible { transform: translate(-3px,-3px); box-shadow: 11px 11px 0 #172E4A; }
.work-card:focus-visible { outline: 3px solid #DC8541; outline-offset: 3px; }
.work-card__media { position: relative; aspect-ratio: 3/4; background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px); overflow: hidden; }
.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.work-card:hover .work-card__media img, .work-card:focus-visible .work-card__media img { transform: scale(1.06); }
.work-card__media--placeholder img { width: 60%; height: 60%; margin: 20%; object-fit: contain; }
.work-card:hover .work-card__media--placeholder img, .work-card:focus-visible .work-card__media--placeholder img { transform: scale(1.08); }
.work-card__no { position: absolute; z-index: 1; top: 16px; left: 16px; margin: 0; font-weight: 700; font-size: 11px; letter-spacing: 0.16em; color: #FFFFFF; background: #172E4A; padding: 7px 14px; border-radius: 999px; transform: rotate(-2deg); }
.work-card__hover {
  position: absolute; inset: 0; z-index: 1; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 22px;
  background: linear-gradient(180deg,rgba(23,46,74,0) 45%,rgba(23,46,74,0.85) 100%);
  opacity: 0; transition: opacity .25s ease;
}
.work-card:hover .work-card__hover, .work-card:focus-visible .work-card__hover { opacity: 1; }
.work-card__hover-text { display: inline-flex; align-items: center; gap: 8px; font-weight: 700; font-size: 13px; letter-spacing: 0.06em; color: #FFFFFF; }
.work-card__hover-text::after { content: "→"; }

@media (min-width: 640px) {
  .work-grid { grid-template-columns: repeat(3,1fr); gap: 24px; }
}

.work-midcta { margin-top: clamp(28px,4vw,40px); text-align: center; }
.work-midcta__link { display: inline-flex; align-items: center; gap: 8px; font-weight: 700; font-size: 14px; color: #A85A1E; border-bottom: 2px solid rgba(168,90,30,0.35); padding-bottom: 4px; transition: border-color .2s ease, color .2s ease; }

