file.content:
/* ============================================
   section 基本パターン
   ============================================ */
.section { position: relative; padding-block: clamp(66px,9vw,120px); background: #FFFFFF; overflow: hidden; }
.section--alt { background: #FFF3E6; }
.section--dark { background: #172E4A; color: #EAF0F6; }
.section--tight { padding-block: clamp(40px,6vw,80px); }

.section__head-row { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(22px,4vw,48px); margin-bottom: clamp(34px,5vw,56px); }
.section__head { flex: 1 1 320px; min-width: 0; max-width: 760px; margin-bottom: clamp(32px,5vw,64px); }
.section__head-row .section__head { margin-bottom: 0; }
.section__head--center { margin-inline: auto; text-align: center; }
.section__body { position: relative; padding-top: clamp(48px,9vw,84px); }
.section__deco {
  position: absolute; top: 0; right: 0; z-index: 2; pointer-events: none;
  width: clamp(120px,17vw,200px); aspect-ratio: 1/1;
  transform: translate(10%,-55%);
}
.section__deco img { width: 100%; height: 100%; object-fit: cover; display: block; }

@media (max-width: 480px) {
  .section__deco { width: clamp(84px,26vw,120px); }
}
.section__eyebrow {
  display: inline-block; margin: 0 0 18px; font-weight: 700; font-size: 11px; line-height: 1;
  letter-spacing: 0.22em; color: #FFFFFF; background: #172E4A; padding: 9px 16px; border-radius: 999px;
  transform: rotate(-2deg);
}
.section--dark .section__eyebrow, .section--cta .section__eyebrow { background: #DC8541; color: #172E4A; }

