import re

lines = open('style.css', encoding='utf-8').read().split('\n')

def split_values(s):
    # split on whitespace but not inside parens
    vals = []
    depth = 0
    cur = ''
    for ch in s:
        if ch == '(':
            depth += 1
            cur += ch
        elif ch == ')':
            depth -= 1
            cur += ch
        elif ch == ' ' and depth == 0:
            if cur:
                vals.append(cur)
                cur = ''
        else:
            cur += ch
    if cur:
        vals.append(cur)
    return vals

pattern = re.compile(r'\b(margin|padding)\s*:\s*([^;]+);')

for i, line in enumerate(lines, 1):
    for m in pattern.finditer(line):
        prop, val = m.group(1), m.group(2).strip()
        vals = split_values(val)
        n = len(vals)
        if n == 1:
            continue  # all sides same, fine
        if n == 2:
            top, rightleft = vals[0], vals[1]
            # 2-value: top/bottom = vals[0], left/right = vals[1] -- symmetric, generally OK unless flagged
            continue
        if n == 3:
            top, rl, bottom = vals
            if bottom != '0' and bottom != top:
                print(f"L{i} [3-val] {prop}: {val}")
        if n == 4:
            top, right, bottom, left = vals
            flag = []
            if right not in ('0','auto') and right != left:
                flag.append('right!=left')
            if bottom not in ('0','auto') and bottom != top:
                flag.append('bottom!=top')
            if flag:
                print(f"L{i} [4-val {','.join(flag)}] {prop}: {val}")
EOF

