110	@keyframes prupru {
111	  0% { transform: rotate(-2deg) translate(0,0); }
112	  12% { transform: rotate(2.4deg) translate(2px,-1px); }
113	  26% { transform: rotate(-3.2deg) translate(-2px,1px); }
114	  40% { transform: rotate(2.6deg) translate(2px,1px); }
115	  54% { transform: rotate(-2.4deg) translate(-1px,-1px); }
116	  68% { transform: rotate(1.6deg) translate(1px,0); }
