174	/* ============================================
175	   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
176	   ============================================ */
177	.menu {
178	  position: fixed; inset: 0; z-index: 95;
179	  background: linear-gradient(160deg,#1B335A 0%,#172E4A 45%,#0F2038 100%);
180	  display: flex; flex-direction: column;
181	  overflow-y: auto; -webkit-overflow-scrolling: touch;
182	  padding: 96px clamp(24px,7vw,56px) 48px;
183	  transition: opacity .4s ease, visibility .4s ease;
184	  opacity: 0; visibility: hidden; pointer-events: none;
185	}
186	.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
187	.menu__cta { margin-bottom: clamp(30px,6vw,48px); }
188	.menu__inner { display: grid; gap: clamp(28px,6vw,44px); width: 100%; max-width: 420px; }
189	.menu__inner > div + div { border-top: 2px dashed rgba(224,185,143,0.28); padding-top: clamp(26px,6vw,40px); }
190	.menu__group-title { display: inline-flex; align-items: center; gap: 10px; font-size: 11px; letter-spacing: 0.24em; color: #E0B98F; margin: 0 0 18px; }
191	.menu__group-title::before { content: ""; width: 16px; height: 2px; background: #DC8541; border-radius: 2px; }
192	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-weight: 700; font-size: 19px; line-height: 1.25; color: #FFFFFF; counter-reset: menu-index; }
193	.menu__nav-list li { counter-increment: menu-index; }
194	.menu__nav-list a {
195	  display: flex; align-items: center; gap: 14px;
196	  padding: 12px 10px; margin-inline: -10px; border-radius: 14px;
197	  transition: transform .3s cubic-bezier(.2,.7,.2,1), color .25s ease, background .25s ease;
198	}
199	.menu__nav-list a::before {
200	  content: counter(menu-index, decimal-leading-zero);
201	  font-family: ui-monospace,Menlo,monospace; font-size: 11px; font-weight: 400;
202	  letter-spacing: 0.08em; color: #DC8541;
203	}
204	.menu__nav-list a::after {
205	  content: "→"; margin-left: auto; font-size: 15px; color: #DC8541;
