598	  position: fixed; right: clamp(14px,3vw,24px); bottom: clamp(14px,3vw,24px); z-index: 90;
599	  width: 52px; height: 52px; border-radius: 50%;
600	  display: flex; align-items: center; justify-content: center;
601	  background: #172E4A; color: #FFFFFF; border: 3px solid #DC8541; font-size: 20px; line-height: 1;
602	  box-shadow: 4px 4px 0 rgba(23,46,74,0.3);
603	  opacity: 0; visibility: hidden; transform: translateY(12px);
604	  transition: opacity .3s ease, transform .3s ease, visibility .3s ease, background .25s ease, color .25s ease;
605	}
606	.back-to-top.is-visible { opacity: 1; visibility: visible; transform: none; }
607	.back-to-top:hover { background: #DC8541; color: #172E4A; }
